import{_ as a,o as i,c as o,R as n}from"./chunks/framework.CGdQ6rU-.js";const u=JSON.parse('{"title":"Japanese Translation Guide","description":"","frontmatter":{},"headers":[],"relativePath":"ja/TRANSLATION_GUIDE.md","filePath":"ja/TRANSLATION_GUIDE.md","lastUpdated":1783589798000}'),t={name:"ja/TRANSLATION_GUIDE.md"};function l(r,e,s,c,d,h){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="japanese-translation-guide" tabindex="-1">Japanese Translation Guide <a class="header-anchor" href="#japanese-translation-guide" aria-label="Permalink to &quot;Japanese Translation Guide&quot;">​</a></h1><p>This guide defines the translation policy for the official Japanese version of the 2025 China Open Source Annual Report.</p><h2 id="japanese-version-maintainer" tabindex="-1">Japanese version maintainer <a class="header-anchor" href="#japanese-version-maintainer" aria-label="Permalink to &quot;Japanese version maintainer&quot;">​</a></h2><p>TAKASU Masakazu（@takasumasakazu） is responsible for the main translation, review, and maintenance of the Japanese version.</p><h2 id="source-policy" tabindex="-1">Source Policy <a class="header-anchor" href="#source-policy" aria-label="Permalink to &quot;Source Policy&quot;">​</a></h2><ul><li>Use the original Chinese version as the primary source.</li><li>The English version may be used only as a reference.</li><li>Do not translate report chapters until a chapter translation task is explicitly started.</li></ul><h2 id="translation-style" tabindex="-1">Translation Style <a class="header-anchor" href="#translation-style" aria-label="Permalink to &quot;Translation Style&quot;">​</a></h2><ul><li>Translate into natural Japanese suitable for an annual report.</li><li>Avoid word-for-word translation when it makes the Japanese text unnatural.</li><li>Keep the tone clear, formal, and consistent across chapters.</li></ul><h2 id="japanese-edition-editorial-note" tabindex="-1">Japanese-Edition Editorial Note <a class="header-anchor" href="#japanese-edition-editorial-note" aria-label="Permalink to &quot;Japanese-Edition Editorial Note&quot;">​</a></h2><ul><li>The Japanese version may include an additional note for Japanese readers.</li><li>If added, it must be clearly labeled as a Japanese-edition editorial note.</li><li>It must not be presented as part of the original Chinese report.</li></ul><h2 id="structure-preservation" tabindex="-1">Structure Preservation <a class="header-anchor" href="#structure-preservation" aria-label="Permalink to &quot;Structure Preservation&quot;">​</a></h2><ul><li>Preserve Markdown structure, heading hierarchy, tables, links, image paths, frontmatter, and references.</li><li>Do not change numbers, data, organization names, project names, URLs, or citations.</li><li>Keep organization and project names unchanged unless <code>ja/glossary.tsv</code> defines a Japanese form.</li></ul><h2 id="visual-assets" tabindex="-1">Visual Assets <a class="header-anchor" href="#visual-assets" aria-label="Permalink to &quot;Visual Assets&quot;">​</a></h2><ul><li>Do not edit, recreate, translate, regenerate, redraw, or replace images, charts, graphs, diagrams, screenshots, SVGs, PNGs, or other visual assets.</li><li>Keep all image paths and references unchanged.</li><li>If an image or chart contains Chinese text, leave the image unchanged.</li><li>If Japanese explanation is needed, add it in the surrounding Japanese text or caption instead of editing the image.</li><li>The Japanese translation should focus on Markdown text, headings, captions, tables, and navigation.</li></ul><h2 id="terminology" tabindex="-1">Terminology <a class="header-anchor" href="#terminology" aria-label="Permalink to &quot;Terminology&quot;">​</a></h2><ul><li>Use <code>ja/glossary.tsv</code> as the source of truth for terminology.</li><li>Do not silently change confirmed glossary entries.</li><li>If a confirmed glossary entry needs revision, discuss it first and update the glossary intentionally.</li><li>If an important term is missing from the glossary, add it with <code>status=needs-review</code>.</li><li>If a term is ambiguous, add a note explaining the ambiguity.</li></ul><h2 id="glossary-status" tabindex="-1">Glossary Status <a class="header-anchor" href="#glossary-status" aria-label="Permalink to &quot;Glossary Status&quot;">​</a></h2><ul><li><code>confirmed</code>: Approved terminology for the Japanese report.</li><li><code>needs-review</code>: Proposed terminology that requires review before broad use.</li></ul><h2 id="japanese-editing-style-for-japanese-oss-readers" tabindex="-1">Japanese editing style for Japanese OSS readers <a class="header-anchor" href="#japanese-editing-style-for-japanese-oss-readers" aria-label="Permalink to &quot;Japanese editing style for Japanese OSS readers&quot;">​</a></h2><ul><li>Write natural Japanese for Japanese open source readers.</li><li>Reduce literal Chinese-style expressions.</li><li>Add concise explanations when a China-specific organization, policy, business term, education term, or ecosystem term would be unclear to Japanese readers.</li><li>Do not over-explain well-known global OSS terms.</li><li>Remove Simplified Chinese text from the Japanese body unless it is necessary as an official name.</li><li>Use English/common names first when available, with Japanese clarification if helpful.</li><li>For Chinese companies and organizations, use English/common name plus Chinese name in parentheses on first appearance when useful.</li><li>Use <code>本章のまとめ</code> instead of <code>小結</code>.</li><li>Use <code>財団</code> for <code>基金会</code> unless it is part of an official organization name.</li><li>Use <code>中国発</code>, <code>中国の</code>, or <code>中国製</code> depending on context; avoid literal <code>中国国産</code>.</li><li>Use <code>車載OS</code> instead of <code>車両OS</code>.</li><li>Use <code>フィジカルAI（Embodied AI）</code> on first appearance, then <code>フィジカルAI</code>.</li><li>Use <code>オムニモーダル</code> rather than <code>全モーダル</code>.</li><li>Avoid slogan-like or literal expressions such as: <ul><li><code>世界のオープンソース事業</code></li><li><code>制度的なインフラ</code></li><li><code>省級</code></li><li><code>普惠</code></li><li><code>能力の高地</code></li><li><code>栄養の還流</code></li><li><code>深水域</code></li><li><code>価値実現</code></li><li><code>商業化実装</code></li><li><code>閉ループ</code></li></ul></li></ul><h2 id="explaining-unfamiliar-concepts-for-japanese-oss-readers" tabindex="-1">Explaining unfamiliar concepts for Japanese OSS readers <a class="header-anchor" href="#explaining-unfamiliar-concepts-for-japanese-oss-readers" aria-label="Permalink to &quot;Explaining unfamiliar concepts for Japanese OSS readers&quot;">​</a></h2><ul><li>When a concept is familiar in Chinese policy, legal, or business discourse but not familiar to Japanese OSS readers, add a short explanation in the text.</li><li>Do not simply translate terms literally if the Japanese reader would not understand the implication.</li><li>Prefer concise explanatory Japanese over leaving a difficult term unexplained.</li><li>Do not over-explain well-known global OSS terms.</li><li>Do not change the legal or factual meaning when adding explanations.</li><li>Avoid overstatement, especially for legal, license, compliance, regulation, and patent topics.</li><li>When explaining legal or regulatory topics, use careful wording such as <code>可能性がある</code>, <code>論点になっている</code>, or <code>と見られます</code> when the source does not establish a definitive conclusion.</li><li>For AI model licensing, distinguish where useful between source code, model weights, training data, generated content, and open-weight models.</li><li>For unfamiliar legal or policy terms, add a short parenthetical or one explanatory sentence.</li><li>For Chinese government bodies, ministries, and planning terms, use a natural Japanese rendering and add a concise role or period explanation when the name alone would be unclear.</li><li>For unfamiliar Chinese organizations or initiatives, use English/common name first where available, and add a Japanese clarification.</li><li>For patent-related topics, explain that <code>特許の開放</code> is different from ordinary source-code open source.</li><li>When future chapters require many Japanese-reader clarifications, prefer updating this guide instead of repeating the same instructions in every Codex prompt.</li></ul><p>Examples:</p><ul><li>permissive license: <code>商用利用・改変・再配布の制約が比較的少ないパーミッシブライセンス</code></li><li>open-weight model: <code>重みを公開するオープンウェイトモデル</code></li><li>SFC v. Vizio: GPLソフトウェアを含む消費者向け製品について、GPLに基づくソースコード開示が争点となったGPL執行の事例。</li><li>EU Cyber Resilience Act（CRA）: 接続されるデジタル製品について、セキュリティ対策や脆弱性対応を求めるEU規制。</li><li>OFAC sanctions: 国境を越えるオープンソース協働にも影響しうる、米国の制裁コンプライアンス。</li><li>patent pool: 複数の組織が関連特許をまとめ、共通ルールの下で利用しやすくする仕組み。</li><li>patent open source / patent opening: source-code open source と同一視せず、<code>特許を一定条件で開放する取り組み</code>として説明する。</li></ul><h2 id="explaining-chinese-policy-and-governance-terms" tabindex="-1">Explaining Chinese policy and governance terms <a class="header-anchor" href="#explaining-chinese-policy-and-governance-terms" aria-label="Permalink to &quot;Explaining Chinese policy and governance terms&quot;">​</a></h2><ul><li>When Chinese government policy terms, ministry names, local government programs, or industrial-policy slogans appear, add concise context for Japanese readers.</li><li>Do not leave policy slogans as literal translations if the implication would be unclear.</li><li>Explain who the policy actor is when helpful, such as a ministry, local government, development zone, foundation, or standards body.</li><li>Explain why the policy matters for open source, rather than only translating the policy name.</li><li>Keep explanations short and factual. Avoid political commentary.</li><li>When a Chinese policy term resembles an official slogan, translate the meaning naturally and avoid slogan-like Japanese.</li><li>For local government measures, add context about the city or region when it helps Japanese readers understand the industrial background.</li><li>For monetary incentives, keep the original amount and explain the policy purpose if needed.</li><li>For long-term plans such as <code>十五五</code>, explain them as the 15th Five-Year Plan or policy proposals toward that plan.</li><li>For AI and open-source policy, distinguish between models, datasets, tools, compute resources, applications, and communities where useful.</li><li>For AI model openness standards, explain that the issue is not only whether something is called “open source,” but which parts are open: source code, model weights, training/evaluation data, licensing terms, and reproducibility.</li><li>For DPI, explain briefly that Digital Public Infrastructure refers to shared digital foundations such as digital ID, payment, and data exchange infrastructure.</li><li>For automotive policy, explain terms such as SDV, vehicle OS, connected vehicles, vehicle AI, datasets, autonomous driving, and next-generation batteries when useful.</li><li>For patent-related policy, explain that “patent opening” is different from ordinary source-code open source.</li><li>For international-policy and diplomacy terms, keep the wording neutral and explain the concrete mechanism, such as standards, foundations, communities, public infrastructure, sanctions, export controls, or rule-making.</li><li>When a chapter requires many Japanese-reader clarifications, prefer updating this guide with reusable rules instead of repeating the same detailed instructions in future prompts.</li></ul><p>Examples:</p><ul><li><code>AI+</code>: explain as a Chinese policy slogan for applying AI across industries and public services.</li><li><code>国家発展改革委員会</code>: explain as an economic policy agency when first mentioned if needed.</li><li><code>工業情報化部</code>: explain as the ministry responsible for industrial policy and information technology when first mentioned if needed.</li><li><code>北京経済技術開発区</code>: explain as a national-level industrial development zone in the Yizhuang area if relevant.</li><li><code>東湖高新区</code>: explain as Wuhan’s major high-tech industrial zone, also known as China Optics Valley, if relevant.</li><li><code>スマートコネクテッドカー</code>: explain as connected vehicles plus autonomous driving, vehicle AI, and vehicle data use.</li><li><code>大規模モデルのオープンソース・オープン等級標準</code>: explain as a standard for evaluating how open a large AI model is.</li><li><code>デジタル公共インフラ（DPI）</code>: explain as shared digital foundations such as digital ID, payment, and data exchange systems.</li></ul><h2 id="open-source-ai-chapter-rules" tabindex="-1">Open Source AI chapter rules <a class="header-anchor" href="#open-source-ai-chapter-rules" aria-label="Permalink to &quot;Open Source AI chapter rules&quot;">​</a></h2><ul><li>Add a concise explanation at first appearance when an AI architecture term is important to understanding the text. Terms that commonly need this treatment include VLM / vision-language model, bounding boxes and JSON output, million-token context, Dense architecture, Mixture of Experts (MoE), expert modules, auxiliary-loss-free load balancing, MLA / Multi-head Latent Attention, KV Cache, long-context models, prefill, RAG, Lost in the Middle, Early Fusion, external image encoders, Context Engineering, Context Rot, Compaction, Context Pyramid, MCP / Model Context Protocol, GraphRAG, TreeRAG, and Passage Reordering.</li><li>Keep explanations reader-facing and short; do not turn the report into a tutorial. Do not explain globally familiar terms such as GitHub, Python, Linux, Hugging Face, Transformer, or JSON.</li><li>Preferred explanation patterns include: <ul><li><code>VLM（視覚言語モデル。画像や動画を言語モデルと組み合わせて理解・処理するモデル）</code></li><li><code>MoE（多数の「エキスパート」と呼ばれる部分モデルのうち、入力ごとに必要な一部だけを使う方式）</code></li><li><code>KV Cache（過去のToken情報を保持し、長文推論でGPUメモリを大量に消費するキャッシュ）</code></li><li><code>Lost in the Middle（長い入力の冒頭と末尾に比べ、中間部分の情報を見落としやすい問題）</code></li><li><code>RAG（Retrieval-Augmented Generation、外部文書を検索して関連情報をモデルに渡す方式）</code></li><li><code>MCP（業務システム、ファイル、API、データベース、開発環境などを必要に応じてモデルへ接続するための共通インターフェース）</code></li></ul></li><li>When a model outputs bounding boxes, coordinates, attributes, or JSON, explain briefly that it produces structured data for downstream business systems, rather than merely describing an image.</li><li>When discussing 1M-token or 10M-token context windows, clarify that the advertised window is often a maximum value; longer context increases cost and latency, prefill can be expensive, and hallucination risk can increase. Note where relevant that practical enterprise systems often combine intelligent chunking with advanced RAG instead of placing everything into one huge context.</li><li>Explain Context Engineering as system design that controls what information enters the model context, in what order and structure, with what freshness, and at what timing. Do not reduce it to better prompt wording.</li><li>Avoid literal or awkward expressions such as <code>生態</code>, <code>賦能</code>, <code>落地</code>, <code>高地</code>, <code>深水域</code>, <code>開源</code>, <code>大モデル</code>, and <code>力任せのスケーリング</code>. Prefer <code>エコシステム</code>, <code>支援する</code> / <code>実現する</code>, <code>実用化</code> / <code>現場導入</code>, <code>オープンソース</code>, <code>大規模モデル</code>, and <code>単純なスケーリング</code> as context requires.</li></ul><h2 id="per-chapter-editing-workflow" tabindex="-1">Per-chapter editing workflow <a class="header-anchor" href="#per-chapter-editing-workflow" aria-label="Permalink to &quot;Per-chapter editing workflow&quot;">​</a></h2><ul><li>Edit only the chapter requested by the user.</li><li>Stop before the next chapter heading.</li><li>Use already-polished previous chapters as style reference.</li><li>If the Japanese is too literal, retranslate the sentence or paragraph from the Chinese source.</li><li>Preserve meaning and factual claims.</li><li>Add glossary entries with <code>status=needs-review</code> when important recurring terms are missing.</li><li>After editing, show <code>git diff --stat</code>, summarize changes, list glossary changes, list remaining Simplified Chinese strings, and do not commit automatically unless asked.</li></ul><h2 id="questionnaire-chapter-rules" tabindex="-1">Questionnaire chapter rules <a class="header-anchor" href="#questionnaire-chapter-rules" aria-label="Permalink to &quot;Questionnaire chapter rules&quot;">​</a></h2><ul><li>In questionnaire chapters, show the original Chinese wording with the Japanese translation on first appearance of a question, answer option, survey category, or response choice, using <code>中国語原文（日本語訳）</code>.</li><li>After the first appearance of the same wording, use only the Japanese translation; do not repeat the Chinese unnecessarily.</li><li>Apply the same rule to questionnaire terminology and actual answer options, for example <code>单选（単一選択）</code>, <code>多选（複数選択）</code>, <code>开放题（自由記述）</code>, <code>受访者（回答者）</code>, <code>有效样本（有効回答）</code>, and <code>非常了解（非常によく知っている）</code>.</li></ul><h2 id="commercialization-chapter-rules" tabindex="-1">Commercialization chapter rules <a class="header-anchor" href="#commercialization-chapter-rules" aria-label="Permalink to &quot;Commercialization chapter rules&quot;">​</a></h2><ul><li>In <code>ja/commercialization.md</code>, use Japanese report-style chapter headings such as <code>## 第一章｜...</code>, <code>## 第二章｜...</code>, and <code>## 第三章｜...</code>; do not use Chinese-style headings such as <code>## 一、...</code>. The introduction may remain <code>## はじめに</code>.</li><li>For Chinese companies, projects, services, and ecosystems that are not widely known in Japan, add a concise parenthetical explanation on first appearance. Keep it short: explain the relevance, not the full company profile.</li><li>In commercialization contexts, explain <code>財団ガバナンス</code> concretely as neutral foundation governance over trademarks, releases, roadmaps, security response, contribution rules, and decision-making among participating companies and communities, rather than single-company control.</li><li>Prefer natural commercialization terms such as <code>事業化</code>, <code>商用導入</code>, <code>収益化</code>, <code>商用ディストリビューション</code>, <code>長期サポート</code>, <code>互換性認証</code>, <code>ハードウェア対応</code>, <code>技術的自立性を高める基盤</code>, <code>業界別の利用シーン</code>, <code>エコシステム</code>, and <code>サプライチェーン</code>.</li><li>Avoid literal Chinese-style expressions such as <code>価値実現</code>, <code>商業化実装</code>, <code>閉ループ</code>, <code>賦能</code>, <code>生態</code>, <code>落地</code>, <code>深水域</code>, <code>高地</code>, <code>ハードウェア適配</code>, and <code>業界別シーン</code>.</li></ul>',36)])])}const m=a(t,[["render",l]]);export{u as __pageData,m as default};
